-- My Recovery Passport: explicit client-safe projection and private reflections
create table if not exists public.recovery_passport_reflections (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, journey_id uuid references public.recovery_journeys(id) on delete cascade, prompt_key text, reflection_text text not null check (char_length(reflection_text)<=4000), visibility text not null default 'PRIVATE_TO_ME' check (visibility in ('PRIVATE_TO_ME','SHARED_WITH_CARE_TEAM')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.passport_visibility_rules (id uuid primary key default gen_random_uuid(), resource_type text not null, event_key text, visibility text not null default 'STAFF_ONLY' check (visibility in ('CLIENT_VISIBLE','CLIENT_VISIBLE_AFTER_REVIEW','STAFF_ONLY','CLINICAL_RESTRICTED','PRIVATE_CLIENT','FAMILY_VISIBLE_WITH_CONSENT')), active boolean not null default true, description text, created_at timestamptz not null default now(), unique(resource_type,event_key));
create table if not exists public.passport_projection_events (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, journey_id uuid references public.recovery_journeys(id) on delete cascade, source_type text not null, source_id text, event_key text not null, visibility text not null default 'STAFF_ONLY', verified_at timestamptz, verified_by uuid, client_safe_payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists idx_passport_reflections_client_created on public.recovery_passport_reflections(client_id,created_at desc); create index if not exists idx_passport_projection_client_created on public.passport_projection_events(client_id,created_at desc); create index if not exists idx_passport_projection_visibility on public.passport_projection_events(visibility,event_key);
alter table public.recovery_passport_reflections enable row level security; alter table public.passport_visibility_rules enable row level security; alter table public.passport_projection_events enable row level security;
create policy passport_reflections_client_select on public.recovery_passport_reflections for select using (client_id in (select p.client_id from public.profiles p where p.auth_user_id=auth.uid() and p.is_active=true and p.role::text='client')); create policy passport_reflections_client_insert on public.recovery_passport_reflections for insert with check (client_id in (select p.client_id from public.profiles p where p.auth_user_id=auth.uid() and p.is_active=true and p.role::text='client')); create policy passport_reflections_client_update on public.recovery_passport_reflections for update using (client_id in (select p.client_id from public.profiles p where p.auth_user_id=auth.uid() and p.is_active=true and p.role::text='client')) with check (client_id in (select p.client_id from public.profiles p where p.auth_user_id=auth.uid() and p.is_active=true and p.role::text='client')); create policy passport_projection_client_select on public.passport_projection_events for select using (visibility='CLIENT_VISIBLE' and verified_at is not null and client_id in (select p.client_id from public.profiles p where p.auth_user_id=auth.uid() and p.is_active=true and p.role::text='client'));
insert into public.passport_visibility_rules(resource_type,event_key,visibility,description) values ('recovery_milestone',null,'CLIENT_VISIBLE_AFTER_REVIEW','Milestones require explicit client approval.'),('journey_stage',null,'CLIENT_VISIBLE','Governed Recovery OS stage and client-safe description.'),('care_goal',null,'CLIENT_VISIBLE_AFTER_REVIEW','Care goals use visible_to_client before projection.'),('appointment',null,'CLIENT_VISIBLE_AFTER_REVIEW','Appointments use visible_to_client before projection.'),('document',null,'CLIENT_VISIBLE_AFTER_REVIEW','Documents use visible_to_client before projection.'),('clinical_note',null,'CLINICAL_RESTRICTED','Raw clinical documentation never projects by default.'),('private_reflection',null,'PRIVATE_CLIENT','Private client reflections remain private by default.') on conflict(resource_type,event_key) do update set visibility=excluded.visibility,description=excluded.description,active=true;